#!/bin/ash
# Runs once in a throwaway Alpine container with /mnt/server bound to the
# same persistent volume that becomes /home/container at runtime — this just
# writes the real startup wrapper there so the egg's "startup" command has
# something to run.
cd /mnt/server

cat > start.sh << 'EOF'
#!/bin/bash
# ONLYOFFICE's own /etc/onlyoffice config paths are read-only under Wings, so
# never try to edit them in place (an earlier version of this egg did via sed
# and failed with "Read-only file system"). Instead: let ONLYOFFICE's bundled
# nginx run completely untouched on its default port 80, then front it with a
# SECOND, independent nginx instance that lives entirely under
# /home/container (writable) and listens on the port Wings actually
# allocated, simply forwarding traffic to 127.0.0.1:80.
set -e

export JWT_ENABLED=true
export JWT_SECRET="${JWT_SECRET}"
export JWT_HEADER=Authorization
export JWT_IN_BODY=true

# Some versions of the image expect these to already exist; harmless if they
# already do, and a plain mkdir won't fail the whole script if the parent is
# read-only elsewhere.
mkdir -p /var/log/onlyoffice/documentserver 2>/dev/null || true

/app/ds/run-document-server.sh &
DS_PID=$!

echo "[egg] Waiting for Document Server on 127.0.0.1:80 ..."
for i in $(seq 1 60); do
  if curl -sf http://127.0.0.1/healthcheck > /dev/null 2>&1; then
    echo "[egg] Document Server is up."
    break
  fi
  if ! kill -0 "$DS_PID" 2>/dev/null; then
    echo "[egg] Document Server process exited early — check the log above for the real error."
    wait "$DS_PID"
    exit 1
  fi
  sleep 5
done

cat > /home/container/proxy-nginx.conf << NGINXEOF
worker_processes 1;
error_log /home/container/proxy-error.log;
pid /home/container/proxy-nginx.pid;
events { worker_connections 128; }
http {
    server {
        listen ${SERVER_PORT};
        client_max_body_size 100m;
        location / {
            proxy_pass http://127.0.0.1:80;
            proxy_set_header Host \$host;
            proxy_set_header X-Real-IP \$remote_addr;
            proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto \$scheme;
            proxy_http_version 1.1;
            proxy_set_header Upgrade \$http_upgrade;
            proxy_set_header Connection "upgrade";
        }
    }
}
NGINXEOF

echo "[egg] Forwarding ${SERVER_PORT} -> 127.0.0.1:80"
exec nginx -c /home/container/proxy-nginx.conf -g "daemon off;"
EOF

chmod +x start.sh
echo "start.sh written to /mnt/server/start.sh"
